                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">Nema uslovljenosti drugim predmetima, ali je poželjno da studenti imaju znanje jezika na nivou IV stepena kako bi pratili ovu nastavu.</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Ovladavanje osnovnim gramatičkim strukturama i služenje jezikom u svakodnevnim situacijama.</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon položenog ispita, student će moći da: - razumije poruke diskursa na teme s kojima se često susreće (porodica, zanimanja, hobiji, bonton, običaji), kao i osnovne poruke složenijih tekstova i slušnih zapisa na različite konkretne i apstraktne teme (umjetnost, putovanja, mediji, školski sistemi, vremenske prilike) na engleskom jeziku, - usmeno se izražava o poznatim temama relativno tečno, koristeći jednostavne strukture, razmjenjuje informacije i učestvuje u razgovoru na poznate i obrađene teme, na engleskom jeziku, - opisuje događaje, iskustva, planove, daje objašnjenja i argumente na engleskom jeziku, - vlada gramatikom engleskog jezika na nižem srednjem nivou, - napiše kraći sastav iz tematskih oblasti koje su poznate i obrađene, na engleskom jeziku, - bude svjestan povezanosti stranog jezika i kulture, i poznaje neke običaje u zemljama engleskog govornog područja.</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Milica Vuković Stamatović, Savo Kostić</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Kratki uvod u odgovarajuće jezičke sadržaje, uz maksimalno učešće studenata u raznim vrstama vježbi – pismene i usmene vježbe u parovima, grupama, kroz prezentacije, diskusije i sl.  </td></tr>
