				</table><h2>Prirodno-matematički fakultet / Matematika i računarske nauke (2017) / RAČUNARI I PROGRAMIRANJE</h2>
				
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Naziv predmeta:</strong></td><td width="80%"><strong>RAČUNARI I PROGRAMIRANJE</strong></td></tr></table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Šifra predmeta</strong></td><td width="20%"><strong>Status predmeta</strong></td><td width="20%"><strong>Semestar</strong></td><td width="20%"><strong>Broj ECTS kredita</strong></td><td width="20%"><strong>Fond časova</strong> (P+V+L)</td></tr>
                <tr ><td width="20%">495</td><td width="20%">Obavezan</td><td width="20%">1</td><td width="20%">6</td><td width="20%">3+3+0</td></tr>
            
                </table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">Nema posebnih preduslova za prijavljivanje i slušanje predmeta.</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Opšti uvodni predmet o računarima. Aritmetičke, logičke i fizičke osnove računara, digitalne mreže u računarskom sistemu. Uvod u programski jezik Pascal. Da se nauči o hardveru računara i o Pascalu.</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da: 1. Nabroji glavne komponente računarskog sistema i ukratko opiše hardver i softver; 2. Opiše kako se podaci (brojevi i drugo) prikazuju u memoriji računara i kako se izvode aritmetičke operacije u binarnom brojnom sistemu; 3. Navede svojstva Booleovih funkcija i rješava zadatke iz te oblasti; 4. Detaljno opiše kombinacione i sekvencijalne mreže u računarskom sistemu, kao što su sabirači, dekoderi, registri i brojači; 5. Objasni uzajamni odnos glavnih komponenti računarskog sistema (procesor, memorija i periferni uređaji); 6. Upotrebljava operativni sistem računara i softverski paket za programski jezik Pascal; 7. Nabroji i opiše vrste podataka i vrste naredbi u programskom jeziku Pascal; 8. Sastavlja programe za rješavanje elementarnih zadataka u razmatranom programskom jeziku.</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Prof. dr Milan Martinović - nastavnik, dipl. mat. Rajko Ćalasan - saradnik.</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Predavanja, vježbe, vježbe u računarskoj učionici, samostalni rad u računarskoj učionici. Samostalni rad-učenje. Konsultacije. </td></tr>
                </table>      
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td><strong>Plan i program rada</strong></td></tr>
				<tr ><td width="100%">
                Pripremne nedjelje - priprema i upis semestra<br>
				I nedjelja, pred. - Šema računara po von Neumannu, razvoj računarske tehnike.<br>
				I nedjelja, vje&#382;be - Uvod o Windowsu i Linuxu.
<br>
				II nedjelja, pred.-Brojni sistemi, konverzija.<br>
				II nedjelja, vje&#382;be O softverskom paketu za Pascal.
<br>
				III nedjelja, pred.- Drugi komplement i pokretni zarez (two's complement, floating point).<br>
				III nedjelja, vje&#382;be - Uvodni pojmovi o programskom jeziku Pascal.
<br>
				IV nedjelja, pred.- Pojam kodiranja, azbučno kodiranje, Huffmanov kod.<br>
				IV nedjelja, vje&#382;be - Pregled svih vrsta podataka u Pascalu.
<br>
				V nedjelja, pred.- O iskaznom računu.<br>
				V nedjelja, vje&#382;be - Podaci tipa integer i real.
<br>
				VI nedjelja, pred.- Pojam Booleove funkcije, glavni identiteti.<br>
				VI nedjelja, vje&#382;be - Podaci tipa char i Boolean.
<br>
				VII nedjelja, pred.- SDNF Booleove funkcije,primjeri kompletnih sistema.<br>
				VII nedjelja, vje&#382;be - Pregled svih vrsta naredbi u Pascalu.
<br>
				VIII nedjelja, pred.- Priprema za prvi kolokvijum (rješavanje zadataka).<br>
				VIII nedjelja, vje&#382;be - Naredbe if, case i goto.
<br>
				IX nedjelja, pred.- * Prvi kolokvijum (gradivo predavanja 20 poena).<br>
				IX nedjelja, vje&#382;be - Naredbe for, while i repeat.
<br>
				X nedjelja, pred.- Kombinacione mreže: sabirač, dekoder, multiplekser.<br>
				X nedjelja, vje&#382;be - Zadaci za vježbu (Pascal).
<br>
				XI nedjelja, pred.- Magistrale digitalnih signala, flipflopovi: SR, D, JK i T.<br>
				XI nedjelja, vje&#382;be - Rad sa nizovima u Pascalu.
<br>
				XII nedjelja, pred.- Sekvencijalne mreže: stacionarni registar, pomerački registar, brojač.<br>
				XII nedjelja, vje&#382;be - Zadaci za vježbu iz raznih oblasti.
<br>
				XIII nedjelja, pred.- Serijski sabirač, primjer aritmetičko-logičke jedinice, memorije: RAM i ROM.<br>
				XIII nedjelja, vje&#382;be - Zadaci za vježbu iz raznih oblasti.
<br>
				XIV nedjelja, pred.- Računar SSEM (Manchester Mark I): ukupni opis računara i primjeri programa.<br>
				XIV nedjelja, vje&#382;be - * Drugi kolokvijum (gradivo vježbi 40 poena), polaže se u računarskoj učionici.
<br>
				XV nedjelja, pred.- Priprema za završni ispit (rješavanje zadataka).<br>
				XV nedjelja, vje&#382;be - Rezervni termin, opšti pregled gradiva.
<br>
                
                </table>  <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0"  width="100%">	
                <tr ><td width="40%"><strong>Optere&#263;enje studenta</strong></td><td width="60%">Nedjeljno: 6 kredita x 40/30 = 8 h. Od toga 3 h predavanja, 3 h vježbi. U semestru (ukupno opterećenje na predmetu): 8 h x 22,5 nedjelja = 180 h. Od toga Nastava i završni ispit 8 h x 16 nedjelja = 128 h.</td></tr>
