							<br>0 sat(a) praktičnog predavanja
							<br>3 vježbi
							<br><strong>2 sat(a) i 0 minuta </strong><br>samostalnog rada, uključujući i konsultacije
							</td>
					<td width="60%">Nastava i završni ispit:
					<br><strong>8 sati i 0 minuta x 16 =128 sati i 0 minuta </strong>
					<br>Neophodna priprema prije početka semestra (administracija, upis, ovjera):
					<br><strong> 8 sati i 0 minuta x 2 =16 sati i 0 minuta </strong>
					<br>Ukupno opterećenje za predmet: 
					<br><strong>6 x 30=180 sati</strong>
					<br>Dopunski rad za pripremu ispita u popravnom ispitnom roku, uključujući i polaganje popravnog ispita od 0 do 30 sati 
					(preostalo vrijeme od prve dvije stavke do ukupnog opterećenja za predmet) 
					<br><strong>36 sati i 0 minuta </strong> 
					<br>Struktura opterećenja: <strong>128 sati i 0 minuta (nastava),
					16 sati i 0 minuta (priprema),
					36 sati i 0 minuta (dopunski rad)</strong>


