			<tr ><td><strong>Obaveze studenta u toku nastave</strong></td><td>Studenti su obavezni da pohađaju predavanja i vježbe, da nauče da samostalno rade u računarskoj učionici, kao i da izađu na dva kolokvijuma i završni ispit.</td></tr>
				<tr ><td><strong>Konsultacije</strong></td><td>Kod nastavnika: nakon časova/po dogovoru, kod saradnika: nakon časova/po dogovoru.</td></tr>
				<tr ><td><strong>Literatura</strong></td><td>(1) M. Martinović, P. Stanišić: Računari i principi programiranja; PMF, Podgorica, 2009. (2) R. Šćepanović, M. Martinović: Uvod u programiranje i zadaci iz Pascala; PMF, Podgorica, 2000.</td></tr>
				<tr ><td><strong>Oblici provjere znanja i ocjenjivanje</strong></td><td>Prvi kolokvijum, drugi kolokvijum i završni ispit (gradivo predavanja 30 poena + gradivo vježbi 10 poena). Prelazna ocjena se dobija ako se ukupno sakupi najmanje 50 poena.</td></tr>
