				</table><h2>Prirodno-matematički fakultet / Matematika i računarske nauke (2017) / LINEARNA ALGEBRA 1</h2>
				
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Naziv predmeta:</strong></td><td width="80%"><strong>LINEARNA ALGEBRA 1</strong></td></tr></table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Šifra predmeta</strong></td><td width="20%"><strong>Status predmeta</strong></td><td width="20%"><strong>Semestar</strong></td><td width="20%"><strong>Broj ECTS kredita</strong></td><td width="20%"><strong>Fond časova</strong> (P+V+L)</td></tr>
                <tr ><td width="20%">3967</td><td width="20%">Obavezan</td><td width="20%">1</td><td width="20%">8</td><td width="20%">4+3+0</td></tr>
            
                </table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">nema</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Upoznavanje studenata sa standardnim kursom Linearne algebre za matematičare. Kurs uključuje teoriju konačnodimenzionalnih vektorskih prostora, matrice, sisteme linearnih jednačina i teoriju linearnih operatora u vektorskim prostorima, uključujući spektralnu teoriju.</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td></td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Vladimir Jaćimović, Dušica Slović
</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>predavanja, vježbe, konsultacije
 </td></tr>
                </table>      
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td><strong>Plan i program rada</strong></td></tr>
				<tr ><td width="100%">
                Pripremne nedjelje - priprema i upis semestra<br>
				I nedjelja, pred. - Grupa i polje. Vektorski prostor. Definicija. Primjeri. Vektorski potprostor. Linearni omotač.<br>
				I nedjelja, vje&#382;be - Grupa i polje. Polja realnih i kompleksnih brojeva. Geometrijski vektori u ravni.
<br>
				II nedjelja, pred.-Linearna zavisnost i nezavisnost vektora. Baza i dimenzija vektorskog prostora. Izomorfizam vektorskih prostora iste dimenzije.

III nedjelja, pred.	Matrice. Rješavanje sistema linearnih jednačina metodom Gausa. Matrice elementarnih transformacija.<br>
				II nedjelja, vje&#382;be Vektorski prostori. Prostori R^n i C^n. Vektorski potprostori. Linearni omotač.
<br>
				III nedjelja, pred.- Matrice. Rješavanje sistema linearnih jednačina metodom Gausa. Matrice elementarnih transformacija.<br>
				III nedjelja, vje&#382;be - Linearna zavisnost i nezavisnost vektora. Baza i dimenzija vektorskog prostora. Zadaci u R^n. Potprostori u R^n. Sistemi linearnih jednačina.
<br>
				IV nedjelja, pred.- Determinanta kvadratne matrice. Rang matrice.
 <br>
				IV nedjelja, vje&#382;be - Metod Gausa za rješavanje sistema linearnih jednačina. Matrice. Matrice elementarnih transformacija.
<br>
				V nedjelja, pred.- Obratna matrica. Regularne i singularne matrice. Matrice prelaska na novu bazu. Ekvivalentne matrice.<br>
				V nedjelja, vje&#382;be - Determinanta i rang matrice.
<br>
				VI nedjelja, pred.- Sistemi linearnih jednačina. Postojanje i jedinstvenost rješenja. Opšte rješenje. Teorema Kronekera-Kapeli. Pravilo Kramera.
<br>
				VI nedjelja, vje&#382;be - Obratna matrica. Regularne i singularne matrice. Matrice prelaska na nove baze.<br>
				VII nedjelja, pred.- I kolokvijum<br>
				VII nedjelja, vje&#382;be - I kolokvijum<br>
				VIII nedjelja, pred.- Slobodna nedjelja<br>
				VIII nedjelja, vje&#382;be - Slobodna nedjelja<br>
				IX nedjelja, pred.- Linearni operatori u vektorskom prostoru. Definicije. Primjeri. Jezgro i slika linearnog operatora.

<br>
				IX nedjelja, vje&#382;be - Sistemi linearnih jednačina. Metodi rješavanja. Postojanje i jedinstvenost rješenja. Homogeni i nehomogeni sistemi. Pravilo Kramera.

<br>
				X nedjelja, pred.- Matrica linearnog operatora. Slične matrice. Obratni operator. Rang linearnog operatora.
<br>
				X nedjelja, vje&#382;be - Linearni operatori u vektorskom prostoru. Jezgro i slika linearnog operatora. Primjeri: operatori projekcije, rotacije, diferenciranja polinoma.<br>
				XI nedjelja, pred.- Invarijantni potprostori linearnog operatora. Svojstvene vrijednosti i vektori. Svojstveni potprostor linearnog operatora.
<br>
				XI nedjelja, vje&#382;be - Matrica linearnog operatora. Obratni operator. Rang linearnog operatora.
<br>
				XII nedjelja, pred.- Osnovna teorema algebre. Karakteristični polinom linearnog operatora. Polinomi od operatora. Teorema Hamiltona-Keli.
<br>
				XII nedjelja, vje&#382;be - Svojstvene vrijednosti i svojstveni vektori linearnog operatora. Karakteristički polinom.<br>
				XIII nedjelja, pred.- Žordanova forma nilpotentnog linearnog operatora.
<br>
				XIII nedjelja, vje&#382;be - Metod nalaženja svojstvenih vektora linearnog operatora. Svojstveni potprostori.
<br>
				XIV nedjelja, pred.- Žordanova forma linearnog operatora u konačnodimenzionalnom vektorskom prostoru. Primjeri.<br>
				XIV nedjelja, vje&#382;be - Žordanova forma i kanonska baza linearnog operatora. Primjeri i zadaci. Slične matrice.<br>
				XV nedjelja, pred.- II kolokvijum<br>
				XV nedjelja, vje&#382;be - II kolokvijum<br>
                
                </table>  <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0"  width="100%">	
                <tr ><td width="40%"><strong>Optere&#263;enje studenta</strong></td><td width="60%">4 predavanja + 3 vježbe + 4 sata samostalnog rada = 11 sati nedjeljno. Ukupan broj sati za nastavu i završni ispit: 16 nedjelja x 11 sati = 176 sati.</td></tr>
				<tr ><td width="40%"><strong>Nedjeljno</strong></td><td  width="60%"><strong>U toku semestra</strong></td></tr>
				<tr ><td width="40%"><strong>8 kredita x 40/30=10 sati i 40 minuta </strong>
							<br>4 sat(a) teorijskog predavanja
							<br>0 sat(a) praktičnog predavanja
							<br>3 vježbi
							<br><strong>3 sat(a) i 40 minuta </strong><br>samostalnog rada, uključujući i konsultacije
							</td>
					<td width="60%">Nastava i završni ispit:
					<br><strong>10 sati i 40 minuta x 16 =170 sati i 40 minuta </strong>
					<br>Neophodna priprema prije početka semestra (administracija, upis, ovjera):
					<br><strong> 10 sati i 40 minuta x 2 =21 sati i 20 minuta </strong>
					<br>Ukupno opterećenje za predmet: 
					<br><strong>8 x 30=240 sati</strong>
					<br>Dopunski rad za pripremu ispita u popravnom ispitnom roku, uključujući i polaganje popravnog ispita od 0 do 30 sati 
					(preostalo vrijeme od prve dvije stavke do ukupnog opterećenja za predmet) 
					<br><strong>48 sati i 0 minuta </strong> 
					<br>Struktura opterećenja: <strong>170 sati i 40 minuta (nastava),
					21 sati i 20 minuta (priprema),
					48 sati i 0 minuta (dopunski rad)</strong>


					</td></tr>
                    
