                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">Nema.</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Predmet ima za cilj  da studenti  usvoje  i  ovladaju osnovama Matematičke analize: teorijom graničnih vrijednosti, elementima diferencijalnog i integralnog računa i teorijom redova.</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da: 1. Definisu osnovne pojmove iz Matematičke analize 1:  skup realnih brojeva, graničnu vrijednost niza i funkcije, diferencijabilnost funkcije, izvod i neodređeni integral na odsječku.  2.  Istaknu osnovna svojstva skupa realnih brojeva. 3. Izvedu osnovna tvrđenja teorije graničnih vrijednosti i diferencijalnog računa, ustanove kada niz ili funkcija imaju graničnu vrijednost ili svojstvo neprekidnosti ili diferencijabilnosti. 4. Ispituju i povezuju svojstva funkcija jedne realne promjenljive primjenom diferencijalnog računa.  5. Stečena znanja primijene u riješavaju najrazličitijih zadatke vezane za navedeni sadržaj matematičke analize. 6 . Stečena znanja primjenjuju u rješavanju realnih zadataka i problema.</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Prof. dr Žarko Pavićević - nastavnik, Nikola Konatar - saradnik</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Predavanja, vježbe, domaći zadaci, konsultacije, kolokvijumi. </td></tr>
                </table>      
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td><strong>Plan i program rada</strong></td></tr>
				<tr ><td width="100%">
                Pripremne nedjelje - priprema i upis semestra<br>
				I nedjelja, pred. - Upoznavanje studenata sa osnovnim temama koje će izučavati u ovom predmetu. <br>
				I nedjelja, vje&#382;be - Upoznavanje studenata sa osnovnim temama koje će izučavati u ovom predmetu. <br>
				II nedjelja, pred.-Skup realnih brojeva-aksiomatsko zasnivanje.<br>
				II nedjelja, vje&#382;be Skup realnih brojeva-aksiomatsko zasnivanje.<br>
				III nedjelja, pred.- Principi kompletnosti skupa realnih brojeva. <br>
