				VIII nedjelja, pred.- Globalna svojstva neprekidnih na segmentu funkcija.<br>
				VIII nedjelja, vje&#382;be - Globalna svojstva neprekidnih na segmentu funkcija.<br>
				IX nedjelja, pred.- Ravnomjerna neprekidnost funkcija.<br>
