				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon položenog ispita, student će moći da: - razlikuje, razumije i koristi najosnovniju matematičku terminologiju na engleskom jeziku iz oblasti teorije brojeva, primijenjene matematike, kombinatorike i diskretne matematike, - pročita jednostavne matematičke izraze na engleskom jeziku, - razumije osnovne poruke popularno-stručnih tekstova iz oblasti matematike na engleskom jeziku, - ostvari samostalnu usmenu i pisanu komunikaciju na engleskom jeziku na srednjem nivou, - usmeno prezentuje na izabranu stručnu temu na engleskom jeziku, - pismeno oblikuje sažetak popularno-stručnog teksta ili slušnog zapisa na engleskom jeziku.</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Milica Vuković Stamatović, Savo Kostić</td></tr>
