                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Naziv predmeta:</strong></td><td width="80%"><strong>UVOD U KOMBINATORIKU</strong></td></tr></table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Šifra predmeta</strong></td><td width="20%"><strong>Status predmeta</strong></td><td width="20%"><strong>Semestar</strong></td><td width="20%"><strong>Broj ECTS kredita</strong></td><td width="20%"><strong>Fond časova</strong> (P+V+L)</td></tr>
                <tr ><td width="20%">3981</td><td width="20%">Obavezan</td><td width="20%">2</td><td width="20%">4</td><td width="20%">2+2+0</td></tr>
            
                </table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">Nema uslovljenosti.</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Upoznavanje sa osnovnim kombinatornim principima</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da: primjenjuje osnovne kombinatorne principe; realne enumerativne probleme predstavlja i rješava primjenom linearnih rekurzija; koristi generatornu funkciju za rješavanje jednostavnijih enumerativnih problema; uočava probleme koji se modeliraju particijoms kupa ili broja; vlada klasičnim kombinatornim metodama i koristi ih u drugim matematičkim disciplinama: vjerovatnoći, algebri, teoriji brojeva, ...</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Prof. dr Žana Kovijanić Vukićević, mr Goran Popivoda</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Predavanja i računske vježbe. Učenje i izrada domaćih zadataka. Konsultacije. </td></tr>
                </table>      
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td><strong>Plan i program rada</strong></td></tr>
				<tr ><td width="100%">
                Pripremne nedjelje - priprema i upis semestra<br>
				I nedjelja, pred. - Uvodno predavanje. Osnovni kombinatorni principi. Dirihleov princip<br>
				I nedjelja, vje&#382;be - Osnovni kombinatorni principi. Dirihleov princip<br>
				II nedjelja, pred.-Osnovni principi prebrojavanja. Permutacije i kombinacije skupova i multiskupova<br>
