				</table><h2>Prirodno-matematički fakultet / Matematika i računarske nauke (2017) / ANALITIČKA GEOMETRIJA</h2>
				
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Naziv predmeta:</strong></td><td width="80%"><strong>ANALITIČKA GEOMETRIJA</strong></td></tr></table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Šifra predmeta</strong></td><td width="20%"><strong>Status predmeta</strong></td><td width="20%"><strong>Semestar</strong></td><td width="20%"><strong>Broj ECTS kredita</strong></td><td width="20%"><strong>Fond časova</strong> (P+V+L)</td></tr>
                <tr ><td width="20%">1341</td><td width="20%">Obavezan</td><td width="20%">2</td><td width="20%">4</td><td width="20%">2+2+0</td></tr>
            
                </table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">Polaganje ovog ispita nije uslovljeno prethodnim polaganjem drugih predmeta.</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Cilj ovog ispita je da upozna studente sa elementima vektorske algebre i  metodom koordinata za ispitivanje geometrijskih objekata i rješavanje geometrijskih problema. </td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da:

1. Opiše Dekartov, polarni i sferni koordinatni sistem i objasni kako se osnovni geometrijski objekti: tačka, prava, ravan, kružnica, elipsa, parabola i hiperbola mogu predstaviti u ovim sistemima. 

2. Objasni kako se jednačine geometrijskih objekata mogu koristiti da bi se uspostavio njihov odnos i položaj u ravni i prostoru. 

3. Ispitaju svojstva geometrijskih objekata koristeći jednačine kojima su opisani.

4. Riješavaju zadatke koristeći metod koordinata.

5. Koristeći jednačine drugog reda sa dvije ili tri promjenljive klasifikuju krive i površi drugog reda.
</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Prof. dr Milojica Jaćimović – nastavnik, Mr. Dušica Slović, saradnik  </td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Predavanja i vježbe sa aktivnim učešćem studenata, domaći zadaci, grupne i individualne konsultacije. </td></tr>
                </table>      
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
