                Pripremne nedjelje - priprema i upis semestra<br>
				I nedjelja, pred. - Dekartov koordinatni sistem u ravni i prostoru. Polarni i sferni koordinatni sistemi.<br>
				I nedjelja, vje&#382;be - Dekartov koordinatni sistem u ravni i prostoru. Polarni i sferni koordinatni sistemi.<br>
				II nedjelja, pred.-Vektori u koordinatnom sistemu. Linearne operacije. Skalarni, vektorski i mješoviti proizvod.<br>
				II nedjelja, vje&#382;be Vektori u koordinatnom sistemu. Linearne operacije. Skalarni, vektorski i mješoviti proizvod.<br>
				III nedjelja, pred.- Krive, površi i njihove jednačine. Primjeri.     <br>
				III nedjelja, vje&#382;be - Krive, površi i njihove jednačine. Primjeri.     <br>
				IV nedjelja, pred.- Prava u ravni, ravan u prostoru, prava u prostoru, razne jednačine prave i ravni.<br>
				IV nedjelja, vje&#382;be - Prava u ravni, ravan u prostoru, prava u prostoru, razne jednačine prave i ravni.<br>
				V nedjelja, pred.- Odnos pravih i ravni u prostoru. Primjeri. Udaljenost tačke od prave i ravni.  <br>
				V nedjelja, vje&#382;be - Odnos pravih i ravni u prostoru. Primjeri. Udaljenost tačke od prave i ravni.  <br>
