				IX nedjelja, pred.- Konveksni skup u n-dimezionalnom prostoru.  Duž, poluprava, poluprostor. Linearno programiranje. Konusni presjeci. Klasifikacija. Kanonske jednačine.<br>
				IX nedjelja, vje&#382;be - Konveksni skup u n-dimezionalnom prostoru.  Duž, poluprava, poluprostor. Linearno programiranje. Konusni presjeci. Klasifikacija. Kanonske jednačine.<br>
				X nedjelja, pred.- Svojstva elipse, hiperbole, parabole. <br>
