				XII nedjelja, pred.- Hiperpovrši drugog reda. Svođenje na kanonski oblik. Teorema o inerciji.<br>
				XII nedjelja, vje&#382;be - Hiperpovrši drugog reda. Svođenje na kanonski oblik. Teorema o inerciji.<br>
