				</table><h2>Prirodno-matematički fakultet / Matematika i računarske nauke (2017) / PRINCIPI PROGRAMIRANJA</h2>
				
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Naziv predmeta:</strong></td><td width="80%"><strong>PRINCIPI PROGRAMIRANJA</strong></td></tr></table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
