                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">Nema posebnih preduslova za prijavljivanje i slušanje predmeta.</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Uvodni predmet o programiranju. Principi programiranja i jezik asemblera. Programski jezik Pascal. Da student nauči hardverske i softverske principe rada računara, kao i Pascal.</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da: 1. Izloži principe organizacije računara na modelu tzv. osnovnog računara; 2. Opiše građu savremenih procesora (Intel 8086 i Pentium); 3. Sastavlja programe na jeziku asemblera; 4. Razumije rad sistema prekida u računaru; 5. Upotrebljava osnovne strukture podataka (liste, redove i stekove) u programima; 6. Opiše potprograme, pokazivače i datoteke u programskom jeziku Pascal; 7. Sastavlja programe za rješavanje zadataka raznog tipa u programskom jeziku Pascal.</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Prof. dr Milan Martinović - nastavnik, dipl. mat. Rajko Ćalasan - saradnik.</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Predavanja, vježbe, vježbe u računarskoj učionici, samostalni rad u računarskoj učionici. Samostalni rad-učenje. Konsultacije. </td></tr>
                </table>      
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td><strong>Plan i program rada</strong></td></tr>
				<tr ><td width="100%">
                Pripremne nedjelje - priprema i upis semestra<br>
				I nedjelja, pred. - Arhitektura osnovnog računara (Mano, basic computer).<br>
				I nedjelja, vje&#382;be - Enumeracije i intervali (vrste podataka u Pascalu).
<br>
				II nedjelja, pred.-Kontrolna jedinica osnovnog računara i vremenski ciklusi.<br>
				II nedjelja, vje&#382;be Rad sa zapisima (RECORD) i skupovima (SET).
<br>
				III nedjelja, pred.- Ulazno-izlazne naredbe i mogućnost prekida (osnovni računar).<br>
				III nedjelja, vje&#382;be - Nizovi i matrice (ARRAY).
<br>
				IV nedjelja, pred.- Primjeri programa za osnovni računar, loader.<br>
				IV nedjelja, vje&#382;be - Zadaci za vježbu (Pascal).
<br>
				V nedjelja, pred.- Pregled razvoja mikroprocesora (od 8-bitnih do 64-bitnih).<br>
				V nedjelja, vje&#382;be - Potprogrami tipa FUNCTION.
<br>
				VI nedjelja, pred.- Procesor Intel 8086: arhitektura i naredbe.<br>
				VI nedjelja, vje&#382;be - Potprogrami tipa PROCEDURE.
<br>
				VII nedjelja, pred.- Upotreba programa debug.exe, primjeri programa na jeziku asemblera.<br>
				VII nedjelja, vje&#382;be - Lokalne promjenljive u potprogramu, rekurzivni potprogrami.
<br>
				VIII nedjelja, pred.- Priprema za prvi kolokvijum (rješavanje zadataka).<br>
				VIII nedjelja, vje&#382;be - Zadaci za vježbu.
<br>
				IX nedjelja, pred.- * Prvi kolokvijum (gradivo predavanja 20 poena).<br>
				IX nedjelja, vje&#382;be - Rad sa datotekama (FILE) u Pascalu.
<br>
				X nedjelja, pred.- Sistem prekida procesora Intel 8086, pregled BIOS-ovih i DOS-ovih prekida.<br>
				X nedjelja, vje&#382;be - Rad sa pokazivačima, ugrađeni potprogrami NEW i DISPOSE.
<br>
				XI nedjelja, pred.- Primjeri programa za ulaz-izlaz (Intel 8086).<br>
				XI nedjelja, vje&#382;be - Rad sa pokazivačima na primjeru lista, stekova i redova.
<br>
				XII nedjelja, pred.- Temeljni pojmovi o operativnim sistemima.<br>
				XII nedjelja, vje&#382;be - Zadaci za vježbu iz raznih oblasti.
<br>
				XIII nedjelja, pred.- Šta je to lista, šta su to stek i red.<br>
				XIII nedjelja, vje&#382;be - Zadaci za vježbu iz raznih oblasti.
<br>
				XIV nedjelja, pred.- Pojam grafa i zadatak o Eulerovom ciklusu, pojam binarnog drveta.<br>
				XIV nedjelja, vje&#382;be - * Drugi kolokvijum (gradivo vježbi 40 poena), polaže se u računarskoj učionici.
<br>
				XV nedjelja, pred.- Priprema za završni ispit (rješavanje zadataka).<br>
				XV nedjelja, vje&#382;be - Rezervni termin, opšti pregled gradiva.
<br>
                
