</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Standardni kurs Linearne algebre II za studente matematike. Uključuje teoriju linearnih operatora u prostorima sa skalarnim proizvodom.
</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td></td></tr>
