                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">Nema.</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Predmet ima za cilj  da studenti  usvoje  i  ovladaju osnovama matematičke analize: teorijom graničnih vrijednosti, elementima diferencijalnog i integralnog računa i teorijom redova.</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da: 
1.	Definišu osnovne pojmove iz matematičke analize 2:  Rimanov integral na segmentu, površinu krivolinijskog trapeza, krivu i dužinu krive, zapreminu i površinu rotacionih tijela, nesvojstveni integral, konvergentne redove. 
2. Izvedu osnovna tvrđenja za Rimanov i nesvojstveni integral i konvergentne redove.
3. Izračunaju Rimanov integral kao graničnu vrijednost niza integralnih suma.
4. Ispituju i povezuju svojstva diferencijabilnosti i integrabilnosti funkcija jedne realne promjenljive. 
5. Primjenjuju neke integralne formule.
6. Stečena znanja primijene u riješavaju najrazličitijih zadataka vezanih za navedeni sadržaj matematičke analize.
7.	Stečena znanja primjenjuju u rješavanju realnih zadataka i problema.
</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Prof. dr Žarko Pavićević - nastavnik, Nikola Konatar - saradnik</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Predavanja, vježbe, domaći zadaci, konsultacije, kolokvijumi. </td></tr>
