				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Predmet ima za cilj osposobljavanje studenta da razumiju i da se razumiju i da 
se služe engleskim jezikom struke.
</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon položenog ispita, student će moći da:
- razumije poruke stručnog diskursa na teme s kojima se često susreće (skupovi, funkcije, geometrijske figure i tijela, ravni...), kao i osnovne poruke složenijih matematičkih tekstova na različite teme na engleskom jeziku,
- usmeno se izražava o matematičkim temama relativno tečno, koristeći jednostavne strukture, razmjenjuje informacije i učestvuje u razgovoru na poznate i obrađene teme, na engleskom jeziku,
- vlada gramatikom engleskog jezika na višem srednjem nivou,
- napiše kraći sastav iz tematskih oblasti koje su poznate i obrađene, na engleskom jeziku,
- uradi prezentaciju na temu vezanu za stručni jezik.
</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Milica Vukovic Stamatovic, Savo Kostic</td></tr>
