                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">Nema uslovljenosti</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Upoznavanje sa osnovnim pojmovima i primjenama teorije grafova</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da: 1. koristi graf kao strukturu podataka,
2. realan problem interpretira kao problem određivanja hromatskog broja ili hromatske klase  grafa,
3. primjenjuje poznata tvrđenja za ispitivanje planarnosti grafova,
4. primjenjuje tvrđenja teorije grafova u  dokazima  korektnosti algoritama, 
5. uočava probleme koji se modeliraju sparivanjem u bipartitnim grafovima.</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Prof. dr Žana Kovijanić Vukićević, mr Goran Popivoda</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Predavanja i računske vježbe. Konsultacije </td></tr>
                </table>      
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td><strong>Plan i program rada</strong></td></tr>
				<tr ><td width="100%">
                Pripremne nedjelje - priprema i upis semestra<br>
				I nedjelja, pred. - Osnovni pojmovi teorije grafova. Izomorfizam grafova. Prezentacije grafa<br>
				I nedjelja, vje&#382;be - Osnovni pojmovi teorije grafova. Izomorfizam grafova. Prezentacije grafa<br>
				II nedjelja, pred.-Dijkstrin algoritam<br>
				II nedjelja, vje&#382;be Dijkstrin algoritam<br>
				III nedjelja, pred.- Stabla<br>
				III nedjelja, vje&#382;be - Stabla<br>
				IV nedjelja, pred.- Matrična teorema o broju razapinjićih stabala. Kejlijeva formula <br>
				IV nedjelja, vje&#382;be - Matrična teorema o broju razapinjićih stabala. Kejlijeva formula <br>
				V nedjelja, pred.- Kruskalov i Primov algoritam<br>
				V nedjelja, vje&#382;be - Kruskalov i Primov algoritam<br>
				VI nedjelja, pred.- Eulerovi i Hamiltonovi putevi<br>
				VI nedjelja, vje&#382;be - Eulerovi i Hamiltonovi putevi<br>
				VII nedjelja, pred.- Problem kineskog poštara. Problem trgovačkog putnika<br>
				VII nedjelja, vje&#382;be - Problem kineskog poštara. Problem trgovačkog putnika<br>
				VIII nedjelja, pred.- Planarni grafovi. Euler-ova teorema. Teorema Pontrjagina-Kuratowskog<br>
				VIII nedjelja, vje&#382;be - Planarni grafovi. Euler-ova teorema. Teorema Pontrjagina-Kuratowskog<br>
				IX nedjelja, pred.- Bojenje grafova<br>
				IX nedjelja, vje&#382;be - Bojenje grafova<br>
				X nedjelja, pred.- Hromatski polinom.  Bojenje planarnih grafova<br>
				X nedjelja, vje&#382;be - Hromatski polinom.  Bojenje planarnih grafova<br>
				XI nedjelja, pred.- Sparivanje u grafovima <br>
				XI nedjelja, vje&#382;be - Sparivanje u grafovima <br>
				XII nedjelja, pred.- Kolokvijum<br>
				XII nedjelja, vje&#382;be - Kolokvijum<br>
				XIII nedjelja, pred.- Sistem različitih predstavnika<br>
				XIII nedjelja, vje&#382;be - Sistem različitih predstavnika<br>
				XIV nedjelja, pred.- Popravni kolokvijum<br>
				XIV nedjelja, vje&#382;be - Popravni kolokvijum<br>
