				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Kroz ovaj predmet studenti se upoznaju sa osnovnim konceptima operativnih sistema, njihovom unutrašnjom strukturom, načinima realizacije, principima i kriterijumima pri dizajnu. Uz to, na vježbama studenti se upoznaju sa glavnim savremenim operativnim sistemima, sa programiranjem korišćenjem sistemskih poziva, kao i sa osnovama shell programiranja.</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da: 
1.	razumije osnovne koncepte operativnih sistema i njihovu unutrašnju strukturu;
2.	razumije načine realizacije, principe i kriterijume pri dizajnu operativnih sistema i koristi ih u programiranju;
3.	koristi i razumije glavne savremene operativne sisteme; 
4.	projektuje i razvija programe korišćenjem sistemskih poziva;
5.	razvija programe korišćenjem shell programiranja.
</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>prof.dr Predrag Stanišić, doc.dr Savo Tomović</td></tr>
