				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student završi ovaj ispit, biće u mogućnosti da: (ili Po završetku ovog kursa student će moći da: ili slično)
1. Definise osnovne algebarske strukture : grupoid, polugrupu, monoid, grupu,prsten, tijelo i polje. 
2. Opise algebru skupova, preslikavanja i prirodnih brojeva.
3. Objasni i prenese pojam mreze, distributivne mreze  i mreze sa komplementima.
4.Objasni i prenese osnovne pojmove teorije grupa kao sto su pojam podgrupe, normalne podgrupe,faktor grupe, ciklicne grupe, izvodne grupe, homomorfizma grupa  i unutrasnjeg automorfizma.
5. Dokaze  i primijeni u zadacima Lagranzovu teoremu i osnovnu teoremu o homomorfizmima grupa. 
</td></tr>
