				</table><h2>Prirodno-matematički fakultet / Matematika i računarske nauke (2017) / PROGRAMIRANJE 1</h2>
				
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Naziv predmeta:</strong></td><td width="80%"><strong>PROGRAMIRANJE 1</strong></td></tr></table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Šifra predmeta</strong></td><td width="20%"><strong>Status predmeta</strong></td><td width="20%"><strong>Semestar</strong></td><td width="20%"><strong>Broj ECTS kredita</strong></td><td width="20%"><strong>Fond časova</strong> (P+V+L)</td></tr>
                <tr ><td width="20%">3983</td><td width="20%">Obavezan</td><td width="20%">3</td><td width="20%">6</td><td width="20%">3+2+0</td></tr>
            
                </table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">Da je položio predmet Računari i programiranje ili predmet Principi programiranja.</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Tjuringove mašine i drugi modeli računara. Da se nauči šta je to računar (u teorijskom smislu) i šta računar može da uradi. Detaljno i kompletno o programskom jeziku C, ilustrovano sa primjerima čiji je nivo intermediate, uz praktičan rad u računarskoj učionici. Da se nauči programski jezik C.</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da: 1. Izloži definiciju Tjuringove mašine i navede niz primjera programa; 2. Navede glavne primjere zadataka koje računar ne može da riješi, kao što su "halting problem" i X Hilbertov problem; 3. Razumije uzajamni odnos intuitivnog pojma algoritma, teorijskog pojma algoritma, realnog kompjutera i modela računara; 4. Opiše pojam vremenske složenosti datog algoritma u slučaju Tjuringove mašine odnosno modela RAM; 5. Navede sve elemente gramatike programskog jezika C; 6. Sastavlja razne programe na programskom jeziku C.</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Prof. dr Milenko Mosurović - nastavnik, MSc Kosta Pavlović - saradnik.</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Predavanja, vježbe, vježbe u računarskoj učionici, samostalni rad u računarskoj učionici. Samostalni rad-učenje. Konsultacije. </td></tr>
                </table>      
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td><strong>Plan i program rada</strong></td></tr>
				<tr ><td width="100%">
                Pripremne nedjelje - priprema i upis semestra<br>
				I nedjelja, pred. - Intuitivni pojam algoritma, Churchova teza, definicija Tjuringove mašine.<br>
				I nedjelja, vje&#382;be - Istorijat programskog jezika C, uvod u jezik C, memorijski koncepti, aritmetika, relacioni operatori.
<br>
				II nedjelja, pred.-Elementarne Tjuringove mašine, definicija Tjuringovog dijagrama. konstrukcija tablice po datom dijagramu.<br>
				II nedjelja, vje&#382;be Top-down metodologija, naredbe uslovnog skoka u jeziku C.
<br>
				III nedjelja, pred.- Dalji primjeri Tjuringovih mašina: R, L, R pisano, L pisano, K, dalji primjeri Tjuringovih mašina: T right,  T left.<br>
				III nedjelja, vje&#382;be - Naredbe kontrole toka, funkcije.
<br>
				IV nedjelja, pred.- Mašina za množenje dva broja P, konverziona funkcija Gamma (s,t), konverziona funkcija Sigma (t,n).<br>
				IV nedjelja, vje&#382;be - Memorijske klase, header datoteke, uvod u rekurziju.
<br>
				V nedjelja, pred.- Predstavljanje Tjuringove mašine pomoću dijagrama koji je sastavljen od elementarnih mašina, mašina T na paragraf.<br>
				V nedjelja, vje&#382;be - Nizovi, uvod u pokazivače.
<br>
				VI nedjelja, pred.- Modeliranje nad azbukom A ind 1.<br>
				VI nedjelja, vje&#382;be - Pokazivači i aritmetika pokazivača, karakteri i stringovi.
<br>
				VII nedjelja, pred.- Normalno računanje po Tjuringu, superpozicija funkcija koje su izračunljive po Tjuringu.<br>
				VII nedjelja, vje&#382;be - Zadaci za vježbu iz raznih oblasti (C).
<br>
