                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">Predmet nije uslovljen drugim predmetima</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Predmet ima za cilj osposobljavanje studenta da razumiju i da se razumiju i da 
se služe engleskim jezikom struke na višem nivou.
</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon položenog ispita, student će moći da:
- razlikuje, razumije i koristi složenu matematičku terminologiju na engleskom jeziku iz oblasti diferencijalne geometrije, topologije, vektorskih prostora i matematičke analize,
- zna da na engleskom jeziku pročita složenije matematičke izraze,
- razumije osnovne poruke popularno-stručnih tekstova iz oblasti matematike na engleskom jeziku,
- ostvari samostalnu usmenu i pisanu komunikaciju na engleskom jeziku na višem srednjem nivou,
- usmeno prezentuje na izabranu stručnu temu na engleskom jeziku.
</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Milica Vukovic Stamatovic, Savo Kostic</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Predavanja i vježbanja. Priprema prezentacije na zadatu temu iz jedne od oblasti sadržaja predmeta. Učenje za kolokvijum i završni ispit. Konsultacije. </td></tr>
                </table>      
