				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Upoznavanje osnovnih algebarskih struktura i pojmova</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da:
-	opiše grupu simetrija i izometrija, direktne proizvode grupa i simetričnu grupu sa dokazom Kelijeve teoreme
-	detaljnije razradi strukturu prstena i definiše podprstene, ideale, maksimalne i proste, faktor-prstene i direktne proizvode prstena
-	dokaže Osnovnu teoremu o homomorfizmima prstena, I i II teoremu o izomorfizmima prstena sa primenama
-	definiše karakteristiku prstena i dokaže osnovne teoreme u vezi sa njom
-	opiše polje razlomaka
-	opiše prsten polinoma i polinomskih funkcija i dokaže osnovne teoreme o faktorizaciji polinoma sa primenom
-	opiše konstrukciju proširenja polja i Euklidove prstene, posebno Euklidov algoritam delenja sa ostatkom sa primenom
</td></tr>
