				</table><h2>Prirodno-matematički fakultet / Matematika i računarske nauke (2017) / DIFERENCIJALNE JEDNAČINE</h2>
				
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Naziv predmeta:</strong></td><td width="80%"><strong>DIFERENCIJALNE JEDNAČINE</strong></td></tr></table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Šifra predmeta</strong></td><td width="20%"><strong>Status predmeta</strong></td><td width="20%"><strong>Semestar</strong></td><td width="20%"><strong>Broj ECTS kredita</strong></td><td width="20%"><strong>Fond časova</strong> (P+V+L)</td></tr>
                <tr ><td width="20%">497</td><td width="20%">Obavezan</td><td width="20%">4</td><td width="20%">6</td><td width="20%">3+2+0</td></tr>
            
                </table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">Nema uslovljenosti</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Upoznavanje studenata sa pojmovima i tvrđenjima iz običnih diferencijalnih jednačina</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da: • prepozna neke probleme iz stvarnog svijeta koji se mogu modelirati diferencijalnim jednačinama; • prepozna i objasni fundamentalne pojmove, poput rješenja jednačine, Cauchyjeve zadatke i osjetljivosti na početne uslove; • klasifikuje diferencijalne jednačine po različitim kriterijumima; • izrazi svojim riječima uslove koji osiguravaju egzistenciju (i jedinstvenost) rješenja Cauchyjevih zadataka; • rješava različite tipove jednačina prvog reda i jednačina višeg reda koje dopuštaju snižavanje reda; • prepozna karakteristična svojstva linearnih jednačina i sistema, koja ih bitno razlikuju od nelinearnih; • rješava linearne jednačine i sisteme; • ispita stabilnost rješenja • prepozna osnovne primjere parcijalnih diferencijalnih jednačina.</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Nevena Mijajlović</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Predavanja, računske vježbe, samostalni rad i konsultacije. </td></tr>
                </table>      
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td><strong>Plan i program rada</strong></td></tr>
				<tr ><td width="100%">
                Pripremne nedjelje - priprema i upis semestra<br>
				I nedjelja, pred. - Diferencijalne jednačine (DJ) prvog reda u normalnom obliku.<br>
				I nedjelja, vje&#382;be - Diferencijalne jednačine (DJ) prvog reda u normalnom obliku.<br>
				II nedjelja, pred.-DJ prvog reda u simetričnom obliku.<br>
				II nedjelja, vje&#382;be DJ prvog reda u simetričnom obliku.<br>
				III nedjelja, pred.- DJ višeg reda. Snižavanje rada. Homogena linearna diferencijalna jednačina (LDJ) n –og reda sa promjenljivim koeficijentima<br>
				III nedjelja, vje&#382;be - DJ višeg reda. Snižavanje rada. Homogena linearna diferencijalna jednačina (LDJ) n –og reda sa promjenljivim koeficijentima<br>
				IV nedjelja, pred.- Nehomogena linearna diferencijalna jednačina (LDJ) n –og reda sa promjenljivim koeficijentima. Metod varijacie konstanti. Homogena LDJ sa konstantnim koeficijentima.<br>
				IV nedjelja, vje&#382;be - Nehomogena linearna diferencijalna jednačina (LDJ) n –og reda sa promjenljivim koeficijentima. Metod varijacie konstanti. Homogena LDJ sa konstantnim koeficijentima.<br>
				V nedjelja, pred.- Nehomogena LDJ n –og reda sa konstantnim koeficijentima. Partikularna rješenja Snižavanje reda LDJ n –og reda kada je poznato m (n manje m) linearno nezavisnih rješenja<br>
				V nedjelja, vje&#382;be - Nehomogena LDJ n –og reda sa konstantnim koeficijentima. Partikularna rješenja Snižavanje reda LDJ n –og reda kada je poznato m (n<m) linearno nezavisnih rješenja<br>
				VI nedjelja, pred.- Nule rješenja LDJ drugog reda (Šturmove teoreme). Sistemi DJ. Metod eliminacije<br>
				VI nedjelja, vje&#382;be - Nule rješenja LDJ drugog reda (Šturmove teoreme). Sistemi DJ. Metod eliminacije<br>
				VII nedjelja, pred.- Homogeni i nehomogeni SLDJ sa promjenljivim koeficijentima. Metod varijacije konstanti<br>
				VII nedjelja, vje&#382;be - Homogeni i nehomogeni SLDJ sa promjenljivim koeficijentima. Metod varijacije konstanti<br>
				VIII nedjelja, pred.- Homogeni SLDJ sa konstantnim koeficijentima. Ojlerova metoda i matrična metoda. Nehomogeni SLDJ sa konstantnim koeficijentima. Partikularna rješenja.<br>
				VIII nedjelja, vje&#382;be - Homogeni SLDJ sa konstantnim koeficijentima. Ojlerova metoda i matrična metoda. Nehomogeni SLDJ sa konstantnim koeficijentima. Partikularna rješenja.<br>
				IX nedjelja, pred.- Kolokvijum<br>
				IX nedjelja, vje&#382;be - Kolokvijum<br>
				X nedjelja, pred.- Snižavanje broja jednačina za rješavanje SLDJ kada su poznato m (m<n) linearno nezavisnih rješenja. Rješavanje jednačina pomoću redova.<br>
				X nedjelja, vje&#382;be - Snižavanje broja jednačina za rješavanje SLDJ kada su poznato m (m<n) linearno nezavisnih rješenja. Rješavanje jednačina pomoću redova.<br>
				XI nedjelja, pred.- Granični zadatak za LDJ i SLDJ.<br>
				XI nedjelja, vje&#382;be - Granični zadatak za LDJ i SLDJ.<br>
				XII nedjelja, pred.- Dokaz teorema o egzistenciji rješenja. Zavisnost rješenja od parametara i počenih uslova<br>
				XII nedjelja, vje&#382;be - Dokaz teorema o egzistenciji rješenja. Zavisnost rješenja od parametara i počenih uslova<br>
				XIII nedjelja, pred.- Dinamički sistemi. Fazni portret. Stabilnost rješenja. Teoreme Ljapunova i Četajeva.<br>
				XIII nedjelja, vje&#382;be - Dinamički sistemi. Fazni portret. Stabilnost rješenja. Teoreme Ljapunova i Četajeva.<br>
				XIV nedjelja, pred.- Parcijalne DJ prvog reda.<br>
				XIV nedjelja, vje&#382;be - Parcijalne DJ prvog reda.<br>
				XV nedjelja, pred.- Popravak kolokvijuma<br>
				XV nedjelja, vje&#382;be - Popravak kolokvijuma<br>
                
                </table>  <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0"  width="100%">	
                <tr ><td width="40%"><strong>Optere&#263;enje studenta</strong></td><td width="60%">4 sata predavanja, 3 sata računskih vježbi, 3 sata i 40 minuta samostalnog rada</td></tr>
