				</table><h2>Prirodno-matematički fakultet / Matematika i računarske nauke (2017) / PROGRAMIRANJE 2</h2>
				
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Naziv predmeta:</strong></td><td width="80%"><strong>PROGRAMIRANJE 2</strong></td></tr></table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Šifra predmeta</strong></td><td width="20%"><strong>Status predmeta</strong></td><td width="20%"><strong>Semestar</strong></td><td width="20%"><strong>Broj ECTS kredita</strong></td><td width="20%"><strong>Fond časova</strong> (P+V+L)</td></tr>
                <tr ><td width="20%">3976</td><td width="20%">Obavezan</td><td width="20%">4</td><td width="20%">6</td><td width="20%">3+2+0</td></tr>
            
                </table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">Da je položio predmet Računari i programiranje ili predmet Principi programiranja.</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Izučavanjem ovog predmeta studenti se upoznaju sa tehnikama i naprednim strukturama podataka za razvoj efikasnih algoritama.</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da: 1. Procjeni složenost algoritma. 2. Konstruiše efikasne algoritme koristeći odgovarajuće tehnike i strukture.
3. Prepozna probleme koji su teško rješivi. 4. Za realne probleme nađe odgovarajući matematički model za koje je poznat algoritam. 
5. Integriše naučene tehnike, strukture i algoritme  pri razvoju složenijih algoritama.</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Prof. dr Milenko Mosurović - nastavnik, MSc Kosta Pavlović - saradnik.</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Predavanja, vježbe, vježbe u računarskoj učionici, samostalni rad u računarskoj učionici. Samostalni rad-učenje. Konsultacije. </td></tr>
                </table>      
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td><strong>Plan i program rada</strong></td></tr>
				<tr ><td width="100%">
                Pripremne nedjelje - priprema i upis semestra<br>
				I nedjelja, pred. - Tehnika podjeli pa vladaj. Karatsubin i Štrasenov algoritam za množenje brojeva i matrica.<br>
				I nedjelja, vje&#382;be - Hip. Prioritetni red<br>
				II nedjelja, pred.-Bektreking (backtracking). Dinamičko programiranje. Pohlepni algoritmi.<br>
				II nedjelja, vje&#382;be AVL - stablo. Crveno crna stabla.<br>
				III nedjelja, pred.- Osnovne operacije nad skupovima. Heš funkcije.<br>
				III nedjelja, vje&#382;be - Backtracking.<br>
				IV nedjelja, pred.- Binomna i Fibonačijeva stabla.<br>
				IV nedjelja, vje&#382;be - Dinamičko programiranje.<br>
				V nedjelja, pred.- Algoritmi na grafovima. DFS, BFS. Stablo koje povezuje (Kruskal,Prim).<br>
				V nedjelja, vje&#382;be - Različiti zadaci iz backtracing-a i dinamičkog programiranja.<br>
				VI nedjelja, pred.- Najkraći put u grafu (jedan izvor, svi čvorovi - Bellman-Ford, Dijkstra, Floyd-Warshall)<br>
				VI nedjelja, vje&#382;be - Grafovi. DFS, BFS.<br>
				VII nedjelja, pred.- Refleksivno tranzitivno zatvorenje grafa. Trouglovi u grafu.<br>
				VII nedjelja, vje&#382;be - Težinski grafovi, Dijkstrin algoritam, Flojd-Versalov algoritam.<br>
				VIII nedjelja, pred.- Segmentno stablo.<br>
				VIII nedjelja, vje&#382;be - Topolosko sortiranje, Kruskalov algoritam, Primov algoritam.<br>
				IX nedjelja, pred.- Traženje uzorka u tekstu (Rabin-Karp, Knuth-Morris-Pratt).<br>
				IX nedjelja, vje&#382;be - Primjena grafova u rješavanju zadataka.<br>
				X nedjelja, pred.- Sufiksno stablo.<br>
				X nedjelja, vje&#382;be - Strogo povezane komponente.<br>
				XI nedjelja, pred.- Kompresija teksta (Hofman, ZL).<br>
				XI nedjelja, vje&#382;be - Segmentno stablo.<br>
				XII nedjelja, pred.- Prošireni Euklidski algoritam. Algoritmi faktorizacije brojeva.<br>
				XII nedjelja, vje&#382;be - Sufiksno stablo.<br>
				XIII nedjelja, pred.- Kolokvijum<br>
				XIII nedjelja, vje&#382;be - Kolokvijum<br>
				XIV nedjelja, pred.- Množenje polinoma i FFT algoritam.<br>
				XIV nedjelja, vje&#382;be - Razni zadaci.<br>
				XV nedjelja, pred.- Popravni kolokvijum<br>
				XV nedjelja, vje&#382;be - Popravni kolokvijum<br>
                
