                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Naziv predmeta:</strong></td><td width="80%"><strong>OBJEKTNO  ORIJENTISANO PROGRAMIRANJE</strong></td></tr></table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Šifra predmeta</strong></td><td width="20%"><strong>Status predmeta</strong></td><td width="20%"><strong>Semestar</strong></td><td width="20%"><strong>Broj ECTS kredita</strong></td><td width="20%"><strong>Fond časova</strong> (P+V+L)</td></tr>
                <tr ><td width="20%">1358</td><td width="20%">Obavezan</td><td width="20%">5</td><td width="20%">3</td><td width="20%">2+1+0</td></tr>
            
                </table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%"></td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Cilj predmeta je da student izuči osnovne i napredne koncepte objektno-orijentisane paradigme programiranja i da ga osposobi za praktično programiranje na jeziku C++.</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što položi ovaj predmet student će biti u mogunosti da i) piše programe na programskom jeziku C++; ii) koristi koncept klase prilikom izrade softvera;iii) upotrebljava koncepte nasljeđivanja i apstraktnih klasa u cilju povezivanja različitih softverskih modula; iv) vrši ponovnu upotrebu programskog koda koristeći koncepte objektno orijentisanog programiranja; v) kreira šablone klasa i operatorske funkcije u programskom jeziku C++.</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Doc. dr Aleksandar Popović – nastavnik, Mr Igor Ivanović - saradnik</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Predavanja i vježbe u računarskoj učionici. Učenje i samostalna izrada praktičnih zadataka. Konsultacije.  </td></tr>
                </table>      
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td><strong>Plan i program rada</strong></td></tr>
				<tr ><td width="100%">
