				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da: 
1.	Definisu osnovne pojmove iz matematičke analize 1:  skup realnih brojeva, graničnu vrijednost niza i funkcije, diferencijabilnost funkcije, izvod i neodređeni integral na odsječku.
2.	 Istaknu osnovna svojstva skupa realnih brojeva. 
3.	Izvedu osnovna tvrđenja teorije graničnih vrijednosti i diferencijalnog računa, ustanove kada niz ili funkcija imaju graničnu vrijednost ili svojstvo neprekidnosti ili diferencijabilnosti.
4.	Ispituju i povezuju svojstva funkcija jedne realne promjenljive primjenom diferencijalnog računa. 
5.	Stečena znanja primijene u riješavaju najrazličitijih zadatke vezane za navedeni sadržaj matematičke analize.
6.	Stečena znanja primjenjuju u rješavanju realnih zadataka i problema.
</td></tr>
