                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">UVOD U KOMPJUTERSKE NAUKE, RAČUNARI I PROGRAMIRANJE, OPERATIVNI SISTEMI, BAZE PODATAKA
</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Kroz ovaj predmet  studenti se upoznaju sa naprednijim konceptima baza podataka, njihovom unutrašnjom strukturom, načinima realizacije, principima i kriterijumima pri dizajnu. Dodatno, studenti se na vježbama upoznaju sa programiranjem vezano za baze podataka.
</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da: 
1.	razumije napredne koncepte sistema baza podataka i njihovu unutrašnju strukturu;
2.	poznaje teorijske osnove logičkog dizajna baze podataka;
3.	razumije načine realizacije, principe i kriterijume pri dizajnu sistema za upravljanje bazama podataka i koristi ih u programiranju;
4.	razumije proces izvršavanja i optimizacije upita;
5.	koristi na naprednom nivou glavne savremene sisteme za upravljanje bazama podataka; 
6.	projektuje i razvija programe korišćenjem savremenih programskih alata i SQL jezika 
</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>prof.  dr. Predrag Stanišić, doc. dr Aleksandar Popović
</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Metod nastave i savladanja gradiva: Predavanja, vježbe u računarskoj učionici / laboratoriji. Učenje i samostalna izrada praktičnih zadataka. Konsultacije.
 </td></tr>
                </table>      
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td><strong>Plan i program rada</strong></td></tr>
				<tr ><td width="100%">
                Pripremne nedjelje - priprema i upis semestra<br>
				I nedjelja, pred. - Administracija sistema baza podataka. Bezbjednost sistema. Korisnici. Prava korisnika.  Uloge.  Rezervno arhiviranje podataka. Replikacija.
<br>
				I nedjelja, vje&#382;be - Administracija sistema baza podataka. Bezbjednost sistema. Korisnici. Prava korisnika.  Uloge.  Rezervno arhiviranje podataka. Replikacija.
<br>
				II nedjelja, pred.-Dizajn relacione baze podataka.  Greške u dizajnu i anomalije. Dekompozicija. Normalne forme. 
<br>
				II nedjelja, vje&#382;be Dizajn relacione baze podataka.  Greške u dizajnu i anomalije. Dekompozicija. Normalne forme. 
<br>
				III nedjelja, pred.- Normalizacija korišćenjem funkcionalnih zavisnosti.  1NF. 2NF. 3NF. BCNF
<br>
				III nedjelja, vje&#382;be - Normalizacija korišćenjem funkcionalnih zavisnosti.  1NF. 2NF. 3NF. BCNF
<br>
				IV nedjelja, pred.- Normalizacija korišćenjem višeznačnih zavisnosti. 4NF.  Normalizacija korišćenjem zavisnosti spajanja. 5NF.  Domen-ključ normalna forma.
<br>
				IV nedjelja, vje&#382;be - Normalizacija korišćenjem višeznačnih zavisnosti. 4NF.  Normalizacija korišćenjem zavisnosti spajanja. 5NF.  Domen-ključ normalna forma.
<br>
				V nedjelja, pred.- Obrada upita. Optimizacija upita. Faze. Informacija u katalogu  potrebna za procjenu plana. Kriterijumi procjene.  Izvršavanje upita. 
<br>
				V nedjelja, vje&#382;be - Obrada upita. Optimizacija upita. Faze. Informacija u katalogu  potrebna za procjenu plana. Kriterijumi procjene.  Izvršavanje upita. 
<br>
				VI nedjelja, pred.- Izbor plana izvršavanja. Procjena i izvršavanje selekcije.  Procjena i izvršavanje spajanja.  Druge operacije.  Evaluacija izraza.
<br>
				VI nedjelja, vje&#382;be - Izbor plana izvršavanja. Procjena i izvršavanje selekcije.  Procjena i izvršavanje spajanja.  Druge operacije.  Evaluacija izraza.
<br>
				VII nedjelja, pred.- Kolokvijum
<br>
				VII nedjelja, vje&#382;be - Kolokvijum<br>
				VIII nedjelja, pred.- Pojam transakcije.  ACID svojstva.  Stanja transakcije. Serijabilnost. <br>
				VIII nedjelja, vje&#382;be - Pojam transakcije.  ACID svojstva.  Stanja transakcije. Serijabilnost. <br>
				IX nedjelja, pred.- Testiranje  serijabilnosti. Definicija transakcije u SQL-u. 
<br>
				IX nedjelja, vje&#382;be - Testiranje  serijabilnosti. Definicija transakcije u SQL-u. <br>
				X nedjelja, pred.- Kontrola konkurentnosti. Protokoli zaključavanja.  Protokoli vremenskih marki. Protokoli zasnovani na validaciji. Granularnost. Viševerzione šeme. Ćorsokaci. Konkurentnost u indeksima<br>
				X nedjelja, vje&#382;be - Kontrola konkurentnosti. Protokoli zaključavanja.  Protokoli vremenskih marki. Protokoli zasnovani na validaciji. Granularnost. Viševerzione šeme. Ćorsokaci. Konkurentnost u indeksima<br>
				XI nedjelja, pred.- Oporavak od kvara. Vrste kvarova.  Oporavak i atomičnost. Šeme za oporavak pomoću žurnala (log-a). Shadow paging. Oporavak sa konkurentnim transakcijama. Upravljanje  baferom. Kvarovi sa gubitkom stabilne memorije.  Naparedne tehnike oporavka.
<br>
				XI nedjelja, vje&#382;be - Oporavak od kvara. Vrste kvarova.  Oporavak i atomičnost. Šeme za oporavak pomoću žurnala (log-a). Shadow paging. Oporavak sa konkurentnim transakcijama. Upravljanje  baferom. Kvarovi sa gubitkom stabilne memorije.  Naparedne tehnike oporavka.
<br>
				XII nedjelja, pred.- Paralelne baze podataka. Paralelizam u bazama podataka.  paralelizam medju upitima. Paralelizam unutar upita. Paralelizam unutar operacije. Paralelizam medju operacijama.  Dizajn paralelnih sistema
<br>
				XII nedjelja, vje&#382;be - Paralelne baze podataka. Paralelizam u bazama podataka.  paralelizam medju upitima. Paralelizam unutar upita. Paralelizam unutar operacije. Paralelizam medju operacijama.  Dizajn paralelnih sistema
<br>
				XIII nedjelja, pred.- Distribuirane baze podataka. Distribuirani sistemi. Mrežna transparentnost. Fragmentacija  podataka. Upravljanje katalogom.  Distribuirana obrada upita<br>
				XIII nedjelja, vje&#382;be - Distribuirane baze podataka. Distribuirani sistemi. Mrežna transparentnost. Fragmentacija  podataka. Upravljanje katalogom.  Distribuirana obrada upita

<br>
				XIV nedjelja, pred.- Nove primjene. Sistemi za podršku pri  odlučivanju. Analiza podataka.  Data mining. Data warehousing.<br>
				XIV nedjelja, vje&#382;be - Nove primjene. Sistemi za podršku pri  odlučivanju. Analiza podataka.  Data mining. Data warehousing.<br>
				XV nedjelja, pred.- Prostorne i geografske baze podataka.  Multimedijalne baze podataka.  Baze podataka na Internetu.  Baze podataka u biologiji. Genom projekat.  Digitalne biblioteke. <br>
				XV nedjelja, vje&#382;be - Odbrana projekta<br>
                
