				</table><h2>Prirodno-matematički fakultet / Matematika i računarske nauke (2017) / RAČUNARSKE MREŽE</h2>
				
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Naziv predmeta:</strong></td><td width="80%"><strong>RAČUNARSKE MREŽE</strong></td></tr></table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Šifra predmeta</strong></td><td width="20%"><strong>Status predmeta</strong></td><td width="20%"><strong>Semestar</strong></td><td width="20%"><strong>Broj ECTS kredita</strong></td><td width="20%"><strong>Fond časova</strong> (P+V+L)</td></tr>
                <tr ><td width="20%">1301</td><td width="20%">Obavezan</td><td width="20%">6</td><td width="20%">5</td><td width="20%">3+2+0</td></tr>
            
                </table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">nema uslovljenosti</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Upoznavanje sa hardverskom i softverskom strukturom i osnovnim karakteristikama računarskih mreža i njihovom praktičnom primjenom. Izučavanje načina i metoda poboljšanja performansi računarskog mreža i povećanja brzine i kvaliteta prenosa podataka.</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Nakon što student položi ovaj ispit, biće u mogućnosti da: 
1.Objasni značaj komunikacija u savremenom svijetu i Interneta, kao osnovne platforme za komunikaciju.
2.Opiše osnovne funkcije, protokole, tehnologije i arhitekture savremenih računarskih mreža. 
3.Stekne vještine potrebne za uspostavljanje i korišćenje lokalnih računarskih mreža i odabranih servisa Interneta.
4.Rješava probleme zastoja i optimizacije računarskih mreža. 
</td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Dr Stevan Šćepanović - predavanja, M. Sc. Ivana Todorović - vježbe</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Predavanja, vježbe u računarskoj učionici / laboratoriji. Učenje i samostalna izrada praktičnih zadataka. Konsultacije. </td></tr>
                </table>      
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td><strong>Plan i program rada</strong></td></tr>
				<tr ><td width="100%">
                Pripremne nedjelje - priprema i upis semestra<br>
				I nedjelja, pred. - Uvod. Osnovni pojmovi o računarskim mrežama i prenosu podataka. Hronologija nastanka i razvoja računarskih mreža. Komunikacije kao bitan segment našeg života.<br>
				I nedjelja, vje&#382;be - Primjeri i zadaci za vježbu.<br>
				II nedjelja, pred.-Mrežni servisi. Klasifikacije računarskih mreža. Globalne i lokalne mreže. Principi izgradnje savremenih računarskih mreža.<br>
				II nedjelja, vje&#382;be Primjeri i zadaci za vježbu.<br>
				III nedjelja, pred.- Slojevita mrežna arhitektura. ISO OSI i TCP/IP model. Aplikativni sloj, funkcionisanje i protokoli.<br>
				III nedjelja, vje&#382;be - Primjeri i zadaci za vježbu.<br>
				IV nedjelja, pred.- Transportni sloj. Principi pouzdanog prenosa podataka i kontrola toka podataka.<br>
				IV nedjelja, vje&#382;be - Primjeri i zadaci za vježbu.<br>
				V nedjelja, pred.- Mrežni sloj OSI modela. Komutacija i metode komutacije. Internetworking. <br>
				V nedjelja, vje&#382;be - Primjeri i zadaci za vježbu.<br>
				VI nedjelja, pred.- Ruteri, osnovne komponente i arhitektura. Algoritmi i protokoli rutiranja.<br>
				VI nedjelja, vje&#382;be - Primjeri i zadaci za vježbu.<br>
				VII nedjelja, pred.- I Kolokvijum. (provjera znanja)<br>
				VII nedjelja, vje&#382;be - Primjeri i zadaci za vježbu.<br>
				VIII nedjelja, pred.- IP adresiranje. Kanalski ili sloj linka podataka. Metode, sredstva i kodovi za kontrolu ispravnosti i pouzdanosti prenosa podataka. Protokoli za korekciju grešaka u kanalskom sloju. Adresiranje na sloju linka podataka u Ethernet mrežama<br>
				VIII nedjelja, vje&#382;be - Primjeri i zadaci za vježbu.<br>
				IX nedjelja, pred.- Fizički sloj. Sredstva i načini za prenos podataka. Pojam i karakteristike komunikacijskog kanala.<br>
				IX nedjelja, vje&#382;be - Primjeri i zadaci za vježbu.<br>
				X nedjelja, pred.- Topologije računarskih mreža. Medijumi za prenos podataka.<br>
				X nedjelja, vje&#382;be - Primjeri i zadaci za vježbu.<br>
				XI nedjelja, pred.- Komunikaciona (mrežna) oprema. Principi i sredstva izgradnje globalnih računarskih <br>
				XI nedjelja, vje&#382;be - Primjeri i zadaci za vježbu.<br>
				XII nedjelja, pred.- Lokalne računarske mreže i komuniciranje kroz medijume sa višestrukim pristupom. <br>
				XII nedjelja, vje&#382;be - Primjeri i zadaci za vježbu.<br>
				XIII nedjelja, pred.- Planiranje i kabliranje mreža, administriranje i upravljanje mrežom.<br>
				XIII nedjelja, vje&#382;be - Primjeri i zadaci za vježbu.<br>
				XIV nedjelja, pred.- II kolokvijum. (provjera znanja)<br>
				XIV nedjelja, vje&#382;be - Konsultacije. Primjeri i zadaci za vježbu.<br>
				XV nedjelja, pred.- Popravni kolokvijum (provjera znanja)<br>
				XV nedjelja, vje&#382;be - Konsultacije<br>
                
