				</table><h2>Prirodno-matematički fakultet / Matematika i računarske nauke (2017) / PARCIJALNE JEDNAČINE</h2>
				
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Naziv predmeta:</strong></td><td width="80%"><strong>PARCIJALNE JEDNAČINE</strong></td></tr></table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%"><strong>Šifra predmeta</strong></td><td width="20%"><strong>Status predmeta</strong></td><td width="20%"><strong>Semestar</strong></td><td width="20%"><strong>Broj ECTS kredita</strong></td><td width="20%"><strong>Fond časova</strong> (P+V+L)</td></tr>
                <tr ><td width="20%">3986</td><td width="20%">Obavezan</td><td width="20%">6</td><td width="20%">5</td><td width="20%">2+2+0</td></tr>
            
                </table>
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td width="20%" ><strong>Studijski programi za koje se organizuje</strong></td><td width="80%"><strong>Matematika i računarske nauke (2017)</strong></td></tr>
                <tr ><td width="20%"><strong>Uslovljenost drugim predmetima</strong></td><td width="80%">Slušanje i polaganje ovog predmeta nije uslovljeno polaganjem drugih predmeta</td></tr>
				
				<tr ><td width="20%"><strong>Ciljevi izu&#269;avanja predmeta</strong></td><td>Cilj ovog predmeta je da se studenti upoznaju sa osnovnim sadržajima parcijalnih diferencijalnih jednačina.</td></tr>
				<tr ><td width="20%"><strong>Ishodi u&#269;enja</strong></td><td>Student će nakon položenog ispita biti u mogućnosti da:
1. Rješava linearne i kvazilinearne PDJ I reda 
2.Klasifikuje linearne PDJ II reda. 
3. Vlada osnovnim metodama za rješavanje sva tri tipa PDJ II reda. 
4. Razumije pojmove jedinstvenosti i neprekidne zavisnosti od početnih uslova. 
5. Razumije fizički smisao ovih jednačina. </td></tr>
				<tr ><td width="20%"><strong>Ime i prezime nastavnika i saradnika</strong></td><td>Prof. dr Oleg Obradović, mr Nikola Konatar</td></tr>
				<tr ><td width="20%"><strong>Metod nastave i savladanja gradiva</strong></td><td>Predavanja, vježbe, konsultacije. </td></tr>
                </table>      
                <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0" width="100%">
                <tr ><td><strong>Plan i program rada</strong></td></tr>
				<tr ><td width="100%">
                Pripremne nedjelje - priprema i upis semestra<br>
				I nedjelja, pred. - Linearne i kvazilinearne PDJ I reda. Metod karakteristika.<br>
				I nedjelja, vje&#382;be - Linearne i kvazilinearne PDJ I reda. Metod karakteristika.<br>
				II nedjelja, pred.-Rješavanje linearnih i kvazilinearnih PDJ I reda.<br>
				II nedjelja, vje&#382;be Rješavanje linearnih i kvazilinearnih PDJ I reda.<br>
				III nedjelja, pred.- Linearna PDJ II reda, opšte napomene.Svodjenje na kanonski oblik linearne PDJ II reda.<br>
				III nedjelja, vje&#382;be - Linearna PDJ II reda, opšte napomene.Svodjenje na kanonski oblik linearne PDJ II reda.<br>
				IV nedjelja, pred.- Klasifikacija linearnih PDJ II reda sa promjenljivim koeficijentima sa dvije nepoznate<br>
				IV nedjelja, vje&#382;be - Klasifikacija linearnih PDJ II reda sa promjenljivim koeficijentima sa dvije nepoznate<br>
				V nedjelja, pred.- Izvodjenje jednačine treperenja strune. Egzistencija rješenja Košijevog problema za beskonačnu strunu. (Dalamberova formula)<br>
				V nedjelja, vje&#382;be - Izvodjenje jednačine treperenja strune. Egzistencija rješenja Košijevog problema za beskonačnu strunu. (Dalamberova formula)<br>
				VI nedjelja, pred.- Jedinstvenost rješenja Košijevog zadatka. Neprekidna zavisnost rješenja od početnih uslova.<br>
				VI nedjelja, vje&#382;be - Jedinstvenost rješenja Košijevog zadatka. Neprekidna zavisnost rješenja od početnih uslova.<br>
				VII nedjelja, pred.- Treperenje polubesk. strune. Talasna jednačina u prostoru i ravni.(Kirhofova i Puasonova formula)<br>
				VII nedjelja, vje&#382;be - Treperenje polubesk. strune. Talasna jednačina u prostoru i ravni.(Kirhofova i Puasonova formula)<br>
				VIII nedjelja, pred.- I kolokvijum<br>
				VIII nedjelja, vje&#382;be - I kolokvijum<br>
				IX nedjelja, pred.- Jednačine paraboličkog tipa, opšte napomene.. Teorema o maksimumu i minimumu. Jedinstvenost rješenja i neprekidna zavisnost od početnih uslova.<br>
				IX nedjelja, vje&#382;be - Jednačine paraboličkog tipa, opšte napomene.. Teorema o maksimumu i minimumu. Jedinstvenost rješenja i neprekidna zavisnost od početnih uslova.<br>
				X nedjelja, pred.- Furijeov metod za jednačine paraboličkog tipa,( Prvi granični zadatak. Drugi granični zadatak)<br>
				X nedjelja, vje&#382;be - Furijeov metod za jednačine paraboličkog tipa,( Prvi granični zadatak. Drugi granični zadatak)<br>
				XI nedjelja, pred.- Rješavanje jednog hiperboličkog zadatka Furijeovim metodom.<br>
				XI nedjelja, vje&#382;be - Rješavanje jednog hiperboličkog zadatka Furijeovim metodom.<br>
				XII nedjelja, pred.- Eliptičke jednačine, opšte napomene.<br>
				XII nedjelja, vje&#382;be - Eliptičke jednačine, opšte napomene.<br>
				XIII nedjelja, pred.- Grinova funkcija za Dirihleov zadatak.( trodimenzionalni slučaj)<br>
				XIII nedjelja, vje&#382;be - Grinova funkcija za Dirihleov zadatak( trodimenzionalni slučaj)<br>
				XIV nedjelja, pred.- Rješenje Dirihleovog zadatka za loptu<br>
				XIV nedjelja, vje&#382;be - Rješenje Dirihleovog zadatka za loptu<br>
				XV nedjelja, pred.- Furijeov metod za eliptičke jednačine. II kolokvijum<br>
				XV nedjelja, vje&#382;be - Furijeov metod za eliptičke jednačine. II kolokvijum<br>
                
                </table>  <table border="1" cellspacing="0" cellpadding="3" bordercolor="#C0C0C0"  width="100%">	
                <tr ><td width="40%"><strong>Optere&#263;enje studenta</strong></td><td width="60%"></td></tr>
				<tr ><td width="40%"><strong>Nedjeljno</strong></td><td  width="60%"><strong>U toku semestra</strong></td></tr>
				<tr ><td width="40%"><strong>5 kredita x 40/30=6 sati i 40 minuta </strong>
							<br>2 sat(a) teorijskog predavanja
							<br>0 sat(a) praktičnog predavanja
							<br>2 vježbi
							<br><strong>2 sat(a) i 40 minuta </strong><br>samostalnog rada, uključujući i konsultacije
							</td>
					<td width="60%">Nastava i završni ispit:
					<br><strong>6 sati i 40 minuta x 16 =106 sati i 40 minuta </strong>
					<br>Neophodna priprema prije početka semestra (administracija, upis, ovjera):
					<br><strong> 6 sati i 40 minuta x 2 =13 sati i 20 minuta </strong>
					<br>Ukupno opterećenje za predmet: 
					<br><strong>5 x 30=150 sati</strong>
					<br>Dopunski rad za pripremu ispita u popravnom ispitnom roku, uključujući i polaganje popravnog ispita od 0 do 30 sati 
					(preostalo vrijeme od prve dvije stavke do ukupnog opterećenja za predmet) 
					<br><strong>30 sati i 0 minuta </strong> 
					<br>Struktura opterećenja: <strong>106 sati i 40 minuta (nastava),
					13 sati i 20 minuta (priprema),
					30 sati i 0 minuta (dopunski rad)</strong>


					</td></tr>
                    
